import{_ as t,o as a,c as o,a2 as i}from"./chunks/framework.DUFi_nbG.js";const u=JSON.parse('{"title":"Project Pitch: Touchless Chef Gesture CV","description":"","frontmatter":{},"headers":[],"relativePath":"00b-project-pitch.md","filePath":"00b-project-pitch.md"}'),n={name:"00b-project-pitch.md"};function r(s,e,c,l,h,d){return a(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="project-pitch-touchless-chef-gesture-cv" tabindex="-1">Project Pitch: Touchless Chef Gesture CV <a class="header-anchor" href="#project-pitch-touchless-chef-gesture-cv" aria-label="Permalink to &quot;Project Pitch: Touchless Chef Gesture CV&quot;">​</a></h1><h2 id="_30-second-elevator-pitch" tabindex="-1">30-Second Elevator Pitch <a class="header-anchor" href="#_30-second-elevator-pitch" aria-label="Permalink to &quot;30-Second Elevator Pitch&quot;">​</a></h2><p>&quot;I built Touchless Chef, a zero-latency computer vision web application that enables hands-free video control for home cooks and workshop makers whose hands are dirty or occupied. Using React 18 and Google MediaPipe Vision Tasks running locally via WebAssembly and WebGL GPU acceleration, it tracks hand landmarks at 30 frames per second without sending a single pixel to an external server. It translates natural gestures like Open Palm and Closed Fist into instant video controls with a 1500ms debounce safety threshold.&quot;</p><h2 id="_2-minute-comprehensive-pitch" tabindex="-1">2-Minute Comprehensive Pitch <a class="header-anchor" href="#_2-minute-comprehensive-pitch" aria-label="Permalink to &quot;2-Minute Comprehensive Pitch&quot;">​</a></h2><p>&quot;Anyone who has ever tried following an online cooking tutorial knows the frustration: your hands are covered in raw chicken, flour, or olive oil, and you need to pause or rewind the video. You either have to wash your hands every few minutes or smudge your expensive device screen.</p><p>To eliminate this friction, I built Touchless Chef. Rather than relying on a heavy cloud-hosted vision API that introduces latency and privacy concerns, I engineered a 100% client-side computer vision pipeline. The application leverages Google&#39;s MediaPipe Tasks Vision framework, pulling pre-compiled WebAssembly binaries and a float16 quantized neural network model running directly on the user&#39;s graphics card via a WebGL delegate.</p><p>The application captures optical video at 640x480 resolution through <code>navigator.mediaDevices.getUserMedia</code>. Inside an optimized <code>requestAnimationFrame</code> render loop, incoming frames are analyzed for 21-point 3D hand landmark topologies. When a gesture—such as an Open Palm to pause or a Closed Fist to play—is detected with greater than 75% confidence, it passes through a 1500ms time-decay debounce filter to eliminate accidental double-triggers.</p><p>Because all tensor math executes locally on the edge, the system achieves sub-20ms interaction latency with zero server bandwidth costs and absolute biometric privacy. It demonstrates how modern browser capabilities can bring practical ambient computing into everyday environments.&quot;</p>',8)])])}const m=t(n,[["render",r]]);export{u as __pageData,m as default};
